# Build the output
# The pattern rotates 180° then tiles with mirroring
input_grid = [[8, 8, 6], [6, 3, 6], [6, 8, 8]]
base = [[8, 8, 6], [6, 3, 6], [6, 8, 8]]  # 180° rotation (same due to symmetry)

output = []
for r in range(9):
    row_out = []
    for col_block in range(3):
        row_offset = r % 3
        for col_offset in range(3):
            # Mirror: if col_block is odd, flip columns
            if col_block % 2 == 1:
                c = 2 - col_offset
            else:
                c = col_offset

            # If row block is odd, flip rows
            if (r // 3) % 2 == 1:
                row_offset = 2 - row_offset

            row_out.append(base[row_offset][c])
    output.append(row_out)

# Pretty print
for row in output:
    print(" ".join(str(x) for x in row))
